const msg = String($input.first().json.original_message || "");
const t = msg.toLowerCase();
const nums = (msg.match(/-?\d+(?:\.\d+)?/g) || []).map(Number);
let output = "";
function round(x){ return Math.round(x * 100) / 100; }
if ((t.includes("heat index") || t.includes("feels like")) && nums.length >= 2) {
  const T = nums[0], R = nums[1];
  const Tf = T * 9/5 + 32;
  let hiF = -42.379 + 2.04901523*Tf + 10.14333127*R - 0.22475541*Tf*R - 0.00683783*Tf*Tf - 0.05481717*R*R + 0.00122874*Tf*Tf*R + 0.00085282*Tf*R*R - 0.00000199*Tf*Tf*R*R;
  const hiC = (hiF - 32) * 5/9;
  output = "Heat Index for " + T + "C at " + R + "% humidity = " + round(hiC) + "C (" + round(hiF) + "F).";
} else if (t.includes("vpd") || t.includes("vapor pressure")) {
  if (nums.length >= 2) {
    const T = nums[0], R = nums[1];
    const svp = 0.6108 * Math.exp((17.27 * T) / (T + 237.3));
    const vpd = svp * (1 - R/100);
    output = "VPD for " + T + "C at " + R + "% humidity = " + round(vpd) + " kPa.";
  } else { output = "To calculate VPD I need temperature (C) and relative humidity (%)."; }
} else if (t.includes("percent") || t.includes("percentage") || t.includes("%")) {
  if (nums.length >= 2) { output = round((nums[0] / nums[1]) * 100) + "% (" + nums[0] + " of " + nums[1] + ")."; }
  else { output = "To compute a percentage I need two numbers."; }
} else if (t.includes("mission criticality") || t.includes("criticality score")) {
  output = "Mission criticality is computed inside the WIaaS pipeline from heat index, VPD, grid surge, and thermal overhead. Ask for a WIaaS analysis of a region to get its score.";
} else if (nums.length >= 2 && /[+\-*x/]/.test(t)) {
  let r = nums[0];
  if (t.includes("+")) r = nums.reduce((a,b)=>a+b,0);
  else if (t.includes("-")) r = nums.reduce((a,b)=>a-b);
  else if (t.includes("x") || t.includes("*")) r = nums.reduce((a,b)=>a*b,1);
  else if (t.includes("/")) r = nums.reduce((a,b)=>a/b);
  output = "Result: " + round(r) + ".";
} else {
  output = "I can calculate heat index (temp + humidity), VPD, percentages, and basic arithmetic. Please include the numbers.";
}
return [{ json: { output, chat_response: output, final_response: output, route: "math_agent" } }];

