    latitude: router.latitude ?? body.latitude ?? context.latitude ?? null,
    longitude: router.longitude ?? body.longitude ?? context.longitude ?? null,
    timezone: router.timezone || body.timezone || context.timezone || '',
  });
}

return [{ json: {
